/// The name for an ISO-2 or ISO-3 [code]; the code itself when unknown.
String lmCountryName(String code) {
  final upper = code.toUpperCase();
  final iso3 = upper.length == 2 ? lmIso2ToIso3[upper] : upper;
  return lmCountryNames[iso3] ?? code;
}
